package com.operators;

public class BitwiseOperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n1 =5;
		int n2 =3;
		System.out.println(n1&n2);
		System.out.println(n1|n2);
		System.out.println(n1^n2);
		System.out.println(~n1);
		System.out.println(n1<<2);
		System.out.println(n1>>2);

	}

}
